// 严格结构门同时核逐期费用与唯一终止；真实声明、占用和资金原语仍需完整本域历史核验。
#include "growth_tactic_lesson_codec.hpp"
#include "resident/domains/interaction/face_to_face_contact.hpp"
#include <algorithm>
#include <charconv>
#include <map>
#include <set>
namespace hanmo::resident {namespace {
bool id(const StableId& value){return !value.empty()&&value.size()<=256;}
bool canonical(const StableId& id,const StableId& prefix){const auto head=prefix+":";if(id.rfind(head,0)!=0)return false;Integer n=0;const auto digits=id.substr(head.size());const auto p=std::from_chars(digits.data(),digits.data()+digits.size(),n);return p.ec==std::errc{}&&p.ptr==digits.data()+digits.size()&&n>0&&std::to_string(n)==digits;}
bool order(const FieldOrder& keys,std::initializer_list<const char*> expected){if(keys.empty())return true;std::set<StableId> wanted;for(const auto* k:expected)wanted.insert(k);return keys.size()==wanted.size()&&std::set<StableId>(keys.begin(),keys.end())==wanted;}
Status commit(const GrowthTacticLessonCommit& b){if(!order(b.field_order,{"result_id","actor_id","kind","request_seq","revision","from_tick","advance"}))return common_failure("BoundaryFieldOrderMismatch");if(b.result_id.empty())return b.actor_id.empty()&&b.kind.empty()&&b.request_seq==0&&b.revision==0&&b.from_tick==-1&&!b.advance?common_success():common_failure("InvalidTacticLessonCommit");return canonical(b.result_id,"result")&&id(b.actor_id)&&id(b.kind)&&b.request_seq>=1&&b.request_seq<=2147483647&&b.revision>=1&&b.from_tick>=0&&b.from_tick<=2147483647?common_success():common_failure("InvalidTacticLessonCommit");}
}
Status validate_growth_tactic_lesson_agreement_shape(const GrowthTacticLessonAgreement& s){
    for(const auto* value:{&s.definition_id,&s.tactic_id,&s.student_id,&s.teacher_id,&s.place_id,&s.payer_wallet_id,&s.recipient_wallet_id,&s.dialogue_id,&s.node_id,&s.session_id,&s.scenario_id})if(!id(*value))return common_failure("InvalidTacticLessonAgreementReference");
    auto fee=growth_tactic_lesson_fee_through(s.total_fee,s.duration,0);if(!fee.ok)return {false,{},fee.error};if(s.student_id==s.teacher_id||s.payer_wallet_id==s.recipient_wallet_id||s.tick<0||s.tick>2147483647-s.duration||s.revision<0||std::all_of(s.world_id.begin(),s.world_id.end(),[](auto b){return b==0;})||!face_to_face_contact_context_valid(s.context)||s.context.kind||s.context.encounter_id||s.context.input_error||s.context.place_id!=s.place_id||s.context.provider_actor_id!=s.teacher_id||s.context.role_id.empty())return common_failure("InvalidTacticLessonAgreement");
    const auto& t=s.teacher_source;const bool initial=t.source_kind=="authored_initial";if((!initial&&t.source_kind!="teaching"&&t.source_kind!="practice")||!canonical(t.acquisition_fact_id,"military_tactic")||!id(t.source_fact_id)||t.acquired_tick<0||t.acquired_tick>s.tick||(initial?(t.initial_grant_id!=t.source_fact_id||t.acquired_tick!=0):!t.initial_grant_id.empty()))return common_failure("InvalidTacticLessonTeacherSource");
    auto q=validate_growth_tactic_lesson_prerequisite_shape(s.prerequisite);if(!q.ok)return q;if(s.prerequisite.observed_tick!=s.tick)return common_failure("InvalidTacticLessonQualificationTime");
    if(!order(s.field_order,{"definition_id","tactic_id","student_id","teacher_id","place_id","payer_wallet_id","recipient_wallet_id","dialogue_id","node_id","session_id","scenario_id","world_id","context","tick","revision","duration","total_fee","teacher_source","prerequisite"})||!order(s.context.field_order,{"place_id","role_id","provider_actor_id"})||!order(t.field_order,{"source_kind","acquisition_fact_id","source_fact_id","initial_grant_id","acquired_tick"})||!order(s.prerequisite.field_order,{"skill_id","origin_kind","initial_prototype_id","required_level","observed_tick","initial_created_tick","initial_xp","minimum_xp","minimum_level","initial_source_ids","study_source_ids"}))return common_failure("BoundaryFieldOrderMismatch");return common_success();
}
Status validate_growth_tactic_lesson_shape(const GrowthTacticLessonState& state){
    if(!order(state.field_order,{"version","starts","credits","closures"})||state.starts.size()>1000000||state.credits.size()>1000000||state.closures.size()>1000000)return common_failure("InvalidTacticLessonState");std::set<StableId> ids,actions,closed;std::map<StableId,Integer> periods;
    for(const auto& row:state.starts.rows()){const auto& f=row.second;if(!canonical(row.first,"tactic_lesson")||!ids.insert(row.first).second||f.kind!="tactic_lesson_started"||!canonical(f.action_id,"action")||!actions.insert(f.action_id).second||!order(f.field_order,{"kind","action_id","agreement","commit"}))return common_failure("InvalidTacticLessonStart",row.first);auto v=validate_growth_tactic_lesson_agreement_shape(f.agreement);if(!v.ok)return v;v=commit(f.commit);if(!v.ok)return v;}
    for(const auto& row:state.credits.rows()){const auto& f=row.second;const auto* start=state.starts.find(f.started_fact_id);if(!canonical(row.first,"tactic_lesson")||!ids.insert(row.first).second||!start||f.kind!="tactic_lesson_credit"||f.action_id!=start->action_id||f.ordinal!=periods[f.started_fact_id]+1||f.ordinal<1||f.ordinal>start->agreement.duration||f.tick<start->agreement.tick||f.tick-start->agreement.tick!=f.ordinal||!order(f.field_order,{"kind","started_fact_id","action_id","tick","ordinal","fee_paid"}))return common_failure("InvalidTacticLessonCredit",row.first);auto fee=growth_tactic_lesson_fee_for_ordinal(start->agreement.total_fee,start->agreement.duration,f.ordinal);if(!fee.ok||fee.value!=f.fee_paid)return common_failure("TacticLessonFeeMismatch",row.first);periods[f.started_fact_id]=f.ordinal;}
    for(const auto& row:state.closures.rows()){const auto& f=row.second;const auto* start=state.starts.find(f.started_fact_id);const bool completed=f.reason=="completed",dead=f.reason=="student_dead"||f.reason=="teacher_dead";const bool unavailable=f.reason=="student_unavailable"||f.reason=="teacher_unavailable";if(!canonical(row.first,"tactic_lesson")||!ids.insert(row.first).second||!start||f.kind!="tactic_lesson_closed"||f.action_id!=start->action_id||(!completed&&!dead&&!unavailable&&f.reason!="student_cancelled")||f.tick<start->agreement.tick||f.provided_half_days!=periods[f.started_fact_id]||f.tick-start->agreement.tick<f.provided_half_days||(completed?(f.provided_half_days!=start->agreement.duration||f.tick-start->agreement.tick!=start->agreement.duration):f.provided_half_days==start->agreement.duration)||((dead||unavailable)?!id(f.cause_fact_id):!f.cause_fact_id.empty())||!closed.insert(f.started_fact_id).second||!order(f.field_order,{"kind","started_fact_id","action_id","reason","cause_fact_id","tick","provided_half_days","fee_paid","fee_released","commit"}))return common_failure("InvalidTacticLessonClosure",row.first);auto paid=growth_tactic_lesson_fee_through(start->agreement.total_fee,start->agreement.duration,f.provided_half_days);if(!paid.ok||f.fee_paid!=paid.value||f.fee_released!=start->agreement.total_fee-paid.value)return common_failure("TacticLessonFeeMismatch",row.first);auto v=commit(f.commit);if(!v.ok)return v;}
    return common_success();
}
}
